CSS='/* Premium UX refinement — 22 Nov 2026. Loaded last to override older layout rules. */\n#payloadSafetyDone{display:none!important}\n#payloadSafetyDialog{height:fit-content;max-height:min(80dvh,600px);padding:20px 22px 12px}\n#payloadSafetyDialog .payload-safety-dialog-head{align-items:center;margin-bottom:12px}\n#payloadSafetyDialog .payload-safety-dialog-head h2{margin:0;font-size:clamp(18px,4.6vw,22px)}\n#payloadSafetyDialog p:last-of-type{margin-bottom:4px}\n#payloadSafetyClose{flex-shrink:0}\n#payloadPage #payloadTab>.notice{display:none!important}\n@media(max-width:900px){\n /* Keep all actions on the same visual row without overlap. */\n #tripsPage>.toolbar,\n #maintenancePage>.toolbar{\n   display:flex!important;flex-flow:row nowrap!important;align-items:center!important;\n   justify-content:space-between!important;gap:8px!important;\n   padding:0!important;margin:12px 0 14px!important;min-height:44px!important;\n   width:100%!important;max-width:100%!important;box-sizing:border-box!important;\n }\n #tripsPage>.toolbar>h2,\n #maintenancePage>.toolbar>h2{\n   flex:1 1 auto!important;min-width:0!important;max-width:none!important;\n   margin:0!important;font-size:clamp(18px,4.8vw,24px)!important;\n   line-height:1.18!important;letter-spacing:-.025em!important;\n }\n #tripsPage>.toolbar>.actions{display:flex!important;flex:0 0 auto!important;gap:0!important;margin:0!important;padding:0!important;min-width:0!important}\n #tripsPage>.toolbar #add,\n #maintenancePage>.toolbar #addMaintenance{\n   display:inline-flex!important;align-items:center!important;justify-content:center!important;\n   flex:0 0 auto!important;width:auto!important;max-width:none!important;\n   min-width:0!important;min-height:42px!important;\n   padding:9px 11px!important;margin:0!important;\n   white-space:nowrap!important;font-size:clamp(12px,3.25vw,14px)!important;line-height:1.1!important;\n   box-sizing:border-box!important;\n }\n /* Existing dashboard pin control is text-based; make it a 42px icon button.\n    Text remains available to assistive tech via aria-label/title. */\n #tripsPage>.toolbar>.ux-page-pinbar.cmh-in-heading,\n #maintenancePage>.toolbar>.ux-page-pinbar.cmh-in-heading{\n   display:flex!important;flex:0 0 42px!important;\n   width:42px!important;min-width:42px!important;max-width:42px!important;\n   padding:0!important;margin:0!important;order:3!important;\n }\n #tripsPage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent,\n #maintenancePage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent{\n   position:relative!important;display:flex!important;align-items:center!important;justify-content:center!important;\n   width:42px!important;min-width:42px!important;max-width:42px!important;\n   height:42px!important;min-height:42px!important;max-height:42px!important;\n   padding:0!important;margin:0!important;border-radius:12px!important;\n   overflow:hidden!important;white-space:nowrap!important;\n   font-size:0!important;line-height:0!important;letter-spacing:0!important;\n   text-indent:0!important;box-sizing:border-box!important;\n }\n #tripsPage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent::before,\n #maintenancePage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent::before{\n   content:"▦"!important;display:block!important;\n   font-size:22px!important;line-height:1!important;font-weight:650!important;color:#164b5b!important;\n }\n #tripsPage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent[aria-pressed="true"]::before,\n #maintenancePage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent[aria-pressed="true"]::before{\n   content:"✓"!important;color:#176c74!important;\n }\n #tripsPage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent:focus-visible,\n #maintenancePage>.toolbar>.ux-page-pinbar.cmh-in-heading #uxPinCurrent:focus-visible{outline:3px solid #168d96!important;outline-offset:2px!important}\n /* Four compact, consistent two-column stat cards. */\n #tripsPage #stats{\n   display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;\n   gap:10px!important;margin-bottom:18px!important;align-items:stretch!important;\n }\n #tripsPage #stats>*{\n   min-width:0!important;min-height:0!important;height:auto!important;\n   padding:14px 15px!important;margin:0!important;\n   display:flex!important;flex-direction:column!important;justify-content:center!important;\n   gap:6px!important;box-sizing:border-box!important;\n }\n #tripsPage #stats strong,\n #tripsPage #stats .value{font-size:clamp(23px,6vw,30px)!important;line-height:1.12!important;margin:0!important}\n #tripsPage #stats .meta,\n #tripsPage #stats small{font-size:12px!important;line-height:1.25!important}\n /* Maintenance page: avoid legacy toolbar\'s huge reserved vertical space. */\n #maintenancePage>.toolbar{margin:14px 0 14px!important;gap:10px!important}\n #maintenancePage>.toolbar #addMaintenance{margin-left:auto!important}\n #maintenancePage .maint-profile{margin-bottom:14px!important}\n #maintenancePage #maintenanceStats{margin-top:0!important}\n}\n@media(max-width:370px){\n #tripsPage>.toolbar>h2,#maintenancePage>.toolbar>h2{font-size:17px!important}\n #tripsPage>.toolbar #add,#maintenancePage>.toolbar #addMaintenance{padding:8px!important;font-size:12px!important}\n #tripsPage #stats>*{padding:12px!important}\n}\n'
JS="(()=>{'use strict';\nfunction sync(){\n const dialog=document.getElementById('payloadSafetyDialog');\n const done=document.getElementById('payloadSafetyDone');\n if(done){done.hidden=true;done.tabIndex=-1;done.setAttribute('aria-hidden','true')}\n const close=document.getElementById('payloadSafetyClose');\n if(close){close.setAttribute('title','Close safety information')}\n // A descriptive label ensures the icon-only dashboard action is understandable.\n const pin=document.getElementById('uxPinCurrent');\n if(pin){\n   const on=pin.getAttribute('aria-pressed')==='true';\n   const label=on?'Remove from my dashboard':'Add to my dashboard';\n   pin.setAttribute('aria-label',label);pin.setAttribute('title',label);\n }\n}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync,{once:true});else sync();\nwindow.addEventListener('planner:navigate',()=>setTimeout(sync,120));\ndocument.addEventListener('click',e=>{if(e.target.closest?.('#uxPinCurrent'))setTimeout(sync,150)});\n})();"

#!/usr/bin/env python3
"""Apply UX release 2026-11-22. Run from the GitHub repository root."""
from pathlib import Path
root=Path.cwd()
html=root/'public/index.html'
if not html.exists():
    raise SystemExit("Run this script from the caravan-trip-planner repository root.")
s=html.read_text(encoding='utf-8')
css='/ux-release-20261122.css?v=1'
js='/ux-release-20261122.js?v=1'
if css not in s:
    if '</head>' not in s: raise SystemExit("Could not locate </head>; no files changed.")
    s=s.replace('</head>',f'<link rel="stylesheet" href="{css}"></head>',1)
if js not in s:
    if '</body>' not in s: raise SystemExit("Could not locate </body>; no files changed.")
    s=s.replace('</body>',f'<script src="{js}" defer></script></body>',1)
(root/'public/ux-release-20261122.css').write_text(CSS,encoding='utf-8')
(root/'public/ux-release-20261122.js').write_text(JS,encoding='utf-8')
html.write_text(s,encoding='utf-8')
print("Installed UX release: compact trip stats, non-overlapping actions, maintenance toolbar and safety dialog.")
print("No SQL migration required. Run git diff --check and node --check public/ux-release-20261122.js.")

